<template><section class="center_view"><div class="head"><div><h2>消息与待办</h2><p>集中处理预约变更、退款和拍摄交付。</p></div><el-button @click="load">刷新</el-button></div><div class="todos"><router-link to="/sheyingshiyuyue">待审核预约 <strong>{{summary.pending||0}}</strong></router-link><router-link to="/booking-changes">预约变更 <strong>{{summary.changeRequests||0}}</strong></router-link><router-link to="/booking-refunds">退款申请 <strong>{{refundCount}}</strong></router-link><router-link to="/sheyingshiyuyue">待交付 <strong>{{summary.delivery||0}}</strong></router-link></div><div class="head"><h3>站内通知</h3><el-button text @click="readAll">全部已读</el-button></div><el-empty v-if="!messages.length" description="暂无通知"/><article v-for="item in messages" :key="item.id" @click="read(item)" :class="{unread:!item.is_read}"><strong>{{item.title}}</strong><p>{{item.content}}</p><small>{{item.created_at}}</small></article><el-pagination class="pager" layout="total, prev, pager, next" :total="total" :page-size="20" v-model:current-page="page" @current-change="load"/></section></template>
<script setup>
import {ref,getCurrentInstance} from 'vue';import {useRouter} from 'vue-router';const http=getCurrentInstance().appContext.config.globalProperties.$http,router=useRouter(),summary=ref({}),refundCount=ref(0),messages=ref([]),total=ref(0),page=ref(1);
async function load(){const [s,r,m]=await Promise.all([http.get('stage3/dashboard/summary'),http.get('booking-refunds',{params:{status:'pending',page:1}}),http.get('sheyingshiyuyue/messages',{params:{page:page.value,limit:20}})]);summary.value=s.data.data||{};refundCount.value=r.data.total||0;messages.value=m.data.data||[];total.value=m.data.total||0}async function read(x){await http.post('sheyingshiyuyue/messages/read/'+x.id);x.is_read=1;window.dispatchEvent(new Event('huahai-messages-changed'));if(x.message_type&&x.message_type.includes('refund'))return router.push('/booking-refunds');if(x.message_type&&x.message_type.includes('change'))return router.push('/booking-changes');if(x.booking_id)router.push({path:'/sheyingshiyuyue',query:{id:x.booking_id}})}async function readAll(){await http.post('sheyingshiyuyue/messages/read-all');window.dispatchEvent(new Event('huahai-messages-changed'));await load()}load()
</script><style scoped>.head{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.head h2,.head h3{margin:0}.head p,small{color:#909399}.todos{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:32px}.todos a{padding:20px;background:var(--el-color-primary-light-9);border-radius:10px;display:flex;justify-content:space-between}.todos strong{color:var(--el-color-primary)}article{padding:18px 14px;border-bottom:1px solid var(--el-border-color-light);cursor:pointer}article p{line-height:1.8;color:var(--el-text-color-regular)}.unread{border-left:3px solid var(--el-color-primary);background:var(--el-color-primary-light-9)}.pager{justify-content:center;margin-top:24px}@media(max-width:900px){.todos{grid-template-columns:repeat(2,1fr)}}</style>
